const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const date = '2018-02-14';
    const greatLakes = ee.FeatureCollection("GLWL/2018_Great_Lakes_Basin_Boundary_V2_Simplified");

    // Filter to get individual lakes
    const lakeErie = greatLakes.filter(ee.Filter.eq('name', 'Erie')).first().geometry();
    const otherGreatLakes = greatLakes.filter(ee.Filter.neq('name', 'Erie')).geometry().dissolve();

    // 2. Data Acquisition & Check
    // Using NOAA/VIIRS/NCDIC_VIIRS_2_NRT for ice concentration
    // This product provides ice concentration in percentage (0-100).
    // The data is daily, so filtering by date should give a single image or a small collection.
    let collection = ee.ImageCollection('NOAA/VIIRS/NCDIC_VIIRS_2_NRT')
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .select('ice_concentration');

    if (collection.size().getInfo() === 0) {
      console.log("No VIIRS ice concentration data found for February 14, 2018.");
      console.log("C1");
      return;
    }

    const image = collection.first();

    // 3. Processing - Calculate mean ice concentration for each region
    const scale = 1000; // Use a reasonable scale to avoid memory errors
    const maxPixels = 1e9; // Increase maxPixels for larger geometries

    // Function to calculate mean ice concentration and pixel count
    const calculateStats = (geometry, name) => {
      const stats = image.reduceRegion({
        reducer: ee.Reducer.mean().combine({
          reducer2: ee.Reducer.count(),
          sharedInputs: true
        }),
        geometry: geometry,
        scale: scale,
        maxPixels: maxPixels
      });

      const meanIce = stats.get('ice_concentration');
      const pixelCount = stats.get('ice_concentration_count');

      return {
        name: name,
        meanIce: meanIce.getInfo(),
        pixelCount: pixelCount.getInfo()
      };
    };

    const erieStats = calculateStats(lakeErie, 'Lake Erie');
    const othersStats = calculateStats(otherGreatLakes, 'Other Great Lakes');

    // 4. Validation & Final Answer
    console.log(`Lake Erie (Ice): ${erieStats.meanIce !== null ? erieStats.meanIce.toFixed(2) : 'N/A'}%, Pixels: ${erieStats.pixelCount}`);
    console.log(`Other Great Lakes (Ice): ${othersStats.meanIce !== null ? othersStats.meanIce.toFixed(2) : 'N/A'}%, Pixels: ${othersStats.pixelCount}`);

    if (erieStats.pixelCount === 0 || othersStats.pixelCount === 0) {
      console.log("No valid pixels remain after processing for one or both regions.");
      console.log("C2");
      return;
    }

    if (erieStats.meanIce === null || othersStats.meanIce === null) {
      console.log("Calculation failed: Mean ice concentration is null for one or both regions.");
      console.log("C3");
      return;
    }

    if (erieStats.meanIce > othersStats.meanIce) {
      console.log("A"); // Yes, Lake Erie has more ice coverage
    } else {
      console.log("B"); // No, Lake Erie does not have more ice coverage
    }

  } catch (error) {
    console.error("An error occurred:", error);
    console.log("D"); // General error
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
